from typing import Any, Callable, Union

from IPython.display import Image as IPythonImage
from PIL import Image as PILImage


# %% ../tutorials/02-stream.ipynb #5eb86a70
def get_image_from_ip_webcam(phone_ip, return_bytes: bool = False, debug_prn: bool = False) -> Union[bytes, IPythonImage]:
    import requests

    phone_url = f"http://{phone_ip}:8080/photo.jpg"

    if debug_prn:
        print(f"retrieving image from phone URL: {phone_url}")

    response = requests.get(phone_url, timeout=10)
    response.raise_for_status()

    if debug_prn:
        print(f"Retrieved {len(response.content)/1000} KB from phone camera.")

    if return_bytes:
        return response.content

    return IPythonImage(data=response.content)

# %% ../tutorials/02-stream.ipynb #040fe005
def _convert_pil_image_to_bytes(image: PILImage.Image) -> bytes:
    from io import BytesIO

    buffer = BytesIO()
    image.save(buffer, format=image.format or "JPEG")
    return buffer.getvalue()

def _convert_ipython_image_to_bytes(image: IPythonImage) -> bytes:
    if image.data is not None:
        return bytes(image.data)

    filename = getattr(image, "filename", None)
    if filename:
        with open(filename, "rb") as f:
            return f.read()

    raise ValueError("IPython image has no data and no filename.")

def _convert_str_to_bytes(value: str) -> bytes:
    return value.encode("utf-8")

def _convert_bytes_to_bytes(value: bytes) -> bytes:
    return value

CONVERTER_FACTORY: dict[type, Callable[[Any], bytes]] = {
    bytes: _convert_bytes_to_bytes,
    str: _convert_str_to_bytes,
    PILImage.Image: _convert_pil_image_to_bytes,
    IPythonImage: _convert_ipython_image_to_bytes,
}

def convert_content_to_bytes(content: Union[str, bytes, IPythonImage, PILImage.Image]) -> bytes:
    for expected_type, converter in CONVERTER_FACTORY.items():
        if isinstance(content, expected_type):
            return converter(content)

    raise ValueError(
        f"Unsupported content type: {type(content).__name__}. Must be bytes, str, PIL.Image.Image, or IPython.display.Image."
    )

# %% ../tutorials/02-stream.ipynb #71c03700
def save_file_with_timestamp(content: Union[bytes, str, IPythonImage, PILImage.Image], filename: str, output_folder: str, debug_prn: bool = False):
    """
    Save the image content to a file with a timestamp in the filename.


    Args:
        content (bytes): The image content to save.
        filename (str): The base filename to use for saving the image.
        output_folder (str): The folder where the image will be saved.
        debug_prn (bool): Whether to print debug information.
    """
    import datetime as dt

    # Get the current timestamp
    timestamp = dt.datetime.now().strftime("%Y%m%d_%H%M%S")

    content: bytes = convert_content_to_bytes(content)

    # Create the full filename with timestamp
    full_filename = f"{output_folder}/{timestamp}_{filename}.jpg"

    # Save the image content to the file
    with open(full_filename, "wb") as f:
        f.write(content)

    if debug_prn:
        print(f"Saved image to {full_filename}")

    return full_filename

# %% ../tutorials/02-stream.ipynb #f0aa0bf0
def get_image_bytes_from_camera(
    phone_ip: str,
    file_name=None,
    output_folder=None,
    return_bytes: bool = True,
    debug_prn: bool = False
) -> Union[str, bytes]:
    """Grab one photo from the camera.


    Args:
        phone_ip: the phone's IP address on your WiFi, e.g. `192.168.1.42`.
        file_name: the name to use for the saved file.
        output_folder: the folder where the image will be saved.
        debug_prn: if True, print what happened.


    Returns:
        Path to the saved JPEG, or the image content as bytes if not saved.
    """

    image_bytes = get_image_from_ip_webcam(phone_ip, return_bytes=True, debug_prn=debug_prn)

    if file_name and output_folder:
        file_path = save_file_with_timestamp(
            content=image_bytes,
            filename=file_name,
            output_folder=output_folder,
        )

        if debug_prn:
            print(f"Saved image to {file_path}")

        if not return_bytes:
            return file_path

    if debug_prn:
        print(f"Retrieved {len(image_bytes)/1000} KB from camera.")

    return image_bytes
